from common import *
A=Author('diagnostic')
def row(sec,num,*fields,**kw):A.row(f'calculus-diagnostic-tests-{num}-{sec}',*fields,**kw)
def alg(num,*fields,**kw):row('algebra',num,*fields,**kw)
alg(1,*[n(k,v) for k,v in zip('abcdef',[81,-81,R(1,81),25,R(9,4),R(1,8)])],why='Exponentiation precedes a leading minus. Use (−3)^4=81, −3^4=−81, a^(−r)=1/a^r, subtract powers in 5^23/5^21, and 16^(−3/4)=1/8.')
alg(2,f('a · Simplified radical',6*s.sqrt(2)),f('b · Simplified product',48*a**5*b**7),f('c · Simplified quotient',x/(9*y**7)),why='Extract square factors in 200 and32. In products add exponents; in quotients subtract them and multiply exponents under an outer power. Part c retains the original domain x>0,y>0.')
alg(3,*[f(k,s.expand(v)) for k,v in zip('abcde',[3*(x+6)+4*(2*x-5),(x+3)*(4*x-5),(s.sqrt(a)+s.sqrt(b))*(s.sqrt(a)-s.sqrt(b)),(2*x+3)**2,(x+2)**3])],why='Distribute every factor; combine like terms. Conjugate radicals multiply to a−b, with a,b≥0.')
alg(4,c('a · Factorization','(2x−5)(2x+5)','(2x−5)^2','(4x−5)(x+5)'),c('b · Factorization','(2x−3)(x+4)','(2x+3)(x−4)','(2x−4)(x+3)'),c('c · Factorization','(x−3)(x−2)(x+2)','(x+3)(x−2)(x+2)','(x−3)(x−2)^2'),c('d · Factorization','x(x+3)(x²−3x+9)','x(x−3)(x²+3x+9)','x(x+3)(x²+3x+9)'),c('e · Factorization, x>0','3(x−1)(x−2)/√x','3√x(x−1)(x−2)','3(x+1)(x+2)/√x'),c('f · Factorization','xy(x−2)(x+2)','xy(x−2)^2','x²y(x−2)(x+2)'),why='Use difference of squares, grouping, sum of cubes and common factors. In e the original negative half power requires x>0; factoring 3/√x leaves x²−3x+2.')
alg(5,f('a · Simplified expression',(x+2)/(x-2)),f('b · Simplified expression',(x-1)/(x-3)),f('c · Simplified expression',1/(x-2)),f('d · Simplified expression',-(x+y)),why='Factor before cancelling, or combine over a common denominator. Original restrictions remain: a x≠−1,2; b x≠−3,3,−1/2; c x≠−2,2; d x≠0,y≠0,x≠y.')
alg(6,f('a · Rationalized expression',5*s.sqrt(2)+2*s.sqrt(10)),f('b · Rationalized expression',1/(s.sqrt(4+h)+2)),why='Multiply numerator and denominator by the conjugate. Part b is equivalent only on its original domain h≥−4,h≠0; the simplified formula also defines its continuous extension at0.')
alg(7,c('a · Completed square','(x+1/2)^2+3/4','(x−1/2)^2+3/4','(x+1/2)^2+1'),c('b · Completed square','2(x−3)^2−7','2(x−3)^2+7','2(x−6)^2−7'),why='Add and subtract the square of half the linear coefficient after factoring the quadratic coefficient: x²+x=(x+1/2)²−1/4 and2(x²−6x)=2(x−3)²−18.')
alg(8,n('a · x',6),n('b · x',1),c('c · Real solutions','{−3,4}','{3,−4}','{−4,4}'),c('d · Real solutions','{−1−√2/2, −1+√2/2}','{1−√2/2, 1+√2/2}','{−1−√2, −1+√2}'),c('e · Real solutions','{−√2,−1,1,√2}','{1,√2}','{−2,−1,1,2}'),c('f · Real solutions','{2/3,22/3}','{−2/3,22/3}','{−6,14}'),n('g · x',R(12,5)),why='Use linear isolation, factoring or the quadratic formula; in e set u=x² and include both signs. In f |x−4|=10/3. For g require x<4, multiply by √(4−x)>0, and solve2x−3(4−x)=0. Check rational equation roots against excluded denominators.')
alg(9,c('a · Interval','[−4,3)','(−4,3]','[−4,3]'),c('b · Interval','(−2,4)','[−2,4]','(−∞,−2) ∪ (4,∞)'),c('c · Interval','(−2,0) ∪ (1,∞)','(−∞,−2) ∪ (0,1)','[−2,0] ∪ [1,∞)'),c('d · Interval','(1,7)','[1,7]','(−7,−1)'),c('e · Interval','(−1,4]','[−1,4]','(−∞,−1) ∪ [4,∞)'),why='Divide the compound inequality by a negative number with reversed signs; factor quadratics/cubics and use a sign chart. For e reduce to (x−4)/(x+1)≤0, excluding the pole−1 and including the zero4.')
alg(10,*[c(k+' · Identity on the real domain where both sides are defined',v,'False' if v=='True' else 'True') for k,v in zip('abcdef',['False','True','False','False','False','True'])],why='a misses2pq; b holds for nonnegative a,b; c square roots do not distribute over sums; d left side is1/C+T; e reciprocals do not distribute over subtraction; f cancel1/x with x≠0,a≠b. Assertions are identities on their common real domains.')
# Analytic geometry
sec='analytic-geometry'
row(sec,1,c('a · Line','y=−3x+1','y=−3x−11','y=3x−11'),c('b · Line','y=−5','x=2','y=2'),c('c · Line','x=2','y=−5','x=−5'),c('d · Line','y=x/2−6','y=2x−9','y=−x/2−4'),why='Use y−y₀=m(x−x₀). Horizontal and vertical lines keep y and x constant. The line2x−4y=3 has slope1/2.')
row(sec,2,c('Circle equation','(x+1)^2+(y−4)^2=52','(x−1)^2+(y+4)^2=52','(x+1)^2+(y−4)^2=26'),why='The center is(−1,4), and squared radius=(3+1)²+(−2−4)²=52.')
row(sec,3,n('Center · x',3),n('Center · y',-5),n('Radius',5),why='Complete squares: (x−3)²+(y+5)²=25; read center(3,−5) and radius5.')
row(sec,4,n('a · Slope',-R(4,3)),c('b · Line equation','4x+3y+16=0','4x−3y+16=0','3x+4y+16=0'),n('b · x-intercept',-4),n('b · y-intercept',-R(16,3)),n('c · Midpoint x',-1),n('c · Midpoint y',-4),n('d · Length',20),c('e · Perpendicular bisector','3x−4y=13','4x+3y=13','3x−4y=−13'),c('f · Circle equation','(x+1)^2+(y+4)^2=100','(x+1)^2+(y+4)^2=400','(x−1)^2+(y−4)^2=100'),why='B−A=(12,−16), slope−4/3 and length20. Average endpoints for midpoint(−1,−4). A perpendicular line has slope3/4 through that midpoint; the diameter circle has radius10.')
row(sec,5,c('a · Region','Horizontal closed strip −1≤y≤3','Vertical closed strip −1≤x≤3','Outside the horizontal strip'),c('b · Region','Open rectangle −4<x<4, −2<y<2','Closed rectangle including all edges','Only the rectangle boundary'),c('c · Region','Below the dashed line y=1−x/2','Above the dashed line y=1−x/2','Below the solid line including boundary'),c('d · Region','On and above the parabola y=x²−1','Strictly below the parabola','On and below the parabola'),c('e · Region','Inside the circle of radius2, excluding its boundary','Inside the circle of radius4','Only the circle boundary'),c('f · Curve','Ellipse centered at origin with horizontal semiaxis4 and vertical semiaxis3','Ellipse with horizontal semiaxis3 and vertical semiaxis4','Filled elliptical disk'),why='Equality includes a boundary; strict inequalities exclude it. Normalize the ellipse as x²/16+y²/9=1. These selections check geometry; retain your own sketches.',limited=True)
# Functions
sec='functions'
row(sec,1,n('a · f(−1)',-2),n('b · f(2), estimate',2.8,tol=.2),c('c · x for f(x)=2','{−3,1}','{−2,3}','{−3,3}'),n('d · Left zero, estimate',-2.5,tol=.2),n('d · Right zero, estimate',.3,tol=.15),c('e · Domain','[−3,3]','[−2,3]','(−∞,∞)'),c('e · Range','[−2,3]','[−3,3]','(−∞,∞)'),why='Read horizontal input and vertical output coordinates from the original graph. Its minimum is(−1,−2), its displayed endpoints span x=−3 to3, and its maximum height is3. Graph estimates use explicit tolerances.')
row(sec,2,f('Simplified difference quotient',12+6*h+h**2),why='Expand(2+h)³−8=12h+6h²+h³ and divide by h, retaining h≠0 in the original quotient.')
row(sec,3,c('a · Domain','ℝ excluding −2 and1','ℝ excluding −1 and2','ℝ'),c('b · Domain','ℝ','[0,∞)','ℝ excluding −1 and1'),c('c · Domain','(−∞,−1] ∪ [1,4]','[−1,4]','(−∞,4]'),why='a denominator factors(x+2)(x−1). b a real cube root permits every real input and x²+1 never vanishes. c impose both4−x≥0 and x²−1≥0.')
row(sec,4,c('a · Transformation','Reflect across the x-axis','Reflect across the y-axis','Translate down1'),c('b · Transformation','Stretch vertically by2, then shift down1','Stretch horizontally by2, then shift down1','Shift down1, then stretch vertically by2'),c('c · Transformation','Shift right3 and up2','Shift left3 and up2','Shift right2 and up3'),why='An outside factor changes vertical values; a minus reflects vertically. Replacing x by x−3 shifts inputs right3, and adding2 shifts outputs up2.')
row(sec,5,c('a · Graph of x³','Increasing cubic through origin with inflection(0,0)','Upward parabola','Decreasing cubic'),c('b · Graph of (x+1)³','Cubic x³ shifted left1','Cubic shifted right1','Cubic shifted up1'),c('c · Graph of (x−2)³+3','Cubic with inflection(2,3)','Cubic with inflection(−2,3)','Cubic with inflection(3,2)'),c('d · Graph of4−x²','Downward parabola, vertex(0,4), zeros±2','Upward parabola, vertex(0,4)','Downward parabola, zeros±4'),c('e · Graph of √x','Increasing concave-down curve from(0,0), x≥0','Increasing curve for all real x','Decreasing curve from(0,0)'),c('f · Graph of2√x','Vertical stretch of √x by2, through(1,2)','Shift √x upward2','Reflection of √x'),c('g · Graph of −2^x','Negative decreasing exponential through(0,−1), asymptote y=0','Positive increasing exponential','Negative increasing exponential through(0,−1)'),c('h · Graph of1+1/x','Hyperbola with asymptotes x=0 and y=1','Hyperbola with asymptotes x=1 and y=0','Parabola with vertex(0,1)'),why='Apply each specified translation, reflection or vertical scale to its parent graph. The selections check characteristic geometry; sketches must still be produced separately.',limited=True)
row(sec,6,n('a · f(−2)',-3),n('a · f(1)',3),c('b · Piecewise graph','Left half of y=1−x² including(0,1); right ray y=2x+1 for x>0','Left half of y=1−x² excluding(0,1); right ray excluding(0,1)','Left half of y=1+x² and right ray y=2x+1'),why='Use the x≤0 branch at−2 and x>0 branch at1. At0 the left branch supplies the closed point(0,1); the right branch approaches it. The graph check identifies branches but does not grade a drawing.',limited=True)
row(sec,7,f('a · f∘g',4*x**2-8*x+2),f('b · g∘f',2*x**2+4*x-5),f('c · g∘g∘g',8*x-21),why='Substitute the entire inner expression before expanding: f(2x−3),2(x²+2x−1)−3,and2(2(2x−3)−3)−3.')
# Trigonometry
sec='trigonometry'
row(sec,1,n('a · Radians',5*s.pi/3,'rad'),n('b · Radians',-s.pi/10,'rad'),why='Multiply degrees by π/180; preserve the negative sign for−18°.')
row(sec,2,n('a · Degrees',150,'degrees'),n('b · Degrees',360/s.pi,'degrees',tol=.05),why='Multiply radians by180/π. Part b is exactly360/π degrees, approximately114.592°.')
row(sec,3,n('Arc length',2*s.pi,'cm'),why='s=rθ with θ in radians:12 cm×π/6=2π cm.')
row(sec,4,n('a · tan(π/3)',s.sqrt(3)),n('b · sin(7π/6)',-R(1,2)),n('c · sec(5π/3)',2),why='Use the30°–60° triangle and quadrant signs; secθ=1/cosθ.')
row(sec,5,c('a · Opposite side','24 sin θ','24 cos θ','24 tan θ'),c('b · Adjacent side','24 cos θ','24 sin θ','24 sec θ'),why='The hypotenuse is24, so opposite=24sinθ and adjacent=24cosθ.')
row(sec,6,n('sin(x+y)',(4+6*s.sqrt(2))/15),why='Both angles are acute: cosx=2√2/3,cosy=4/5,siny=3/5. Then sin(x+y)=sinxcosy+cosxsiny=(4+6√2)/15.')
row(sec,7,c('a · Key simplification','(sin²θ+cos²θ)/cosθ = 1/cosθ','(sinθ+cosθ)/cosθ = 1','sin²θ+cos²θ = secθ'),c('b · Key simplification','2sinx cosx = sin2x','2sinx/cosx = sin2x','sin²x+cos²x = sin2x'),why='a put tanθsinθ and cosθ over cosθ and use the Pythagorean identity; require cosθ≠0. b divide2tanx bysec²x to obtain2sinxcosx; require cosx≠0. These check the crucial identities, not the written proof.',limited=True)
row(sec,8,c('Solutions in [0,2π]','{0,π/3,π,5π/3,2π}','{π/3,5π/3}','{0,π,2π}'),why='sin2x−sinx=sinx(2cosx−1)=0. Include both endpoint roots along withπ and the two angles with cosx=1/2.')
row(sec,9,n('Amplitude',1),n('Period',s.pi,'rad'),n('Midline y',1),c('Graph phase','At x=0, y=1 and the curve rises toward its first maximum at x=π/4','At x=0, y=2 and the curve falls','At x=0, y=1 and the curve falls'),why='The outer1 shifts sine upward, and2x halves its period toπ. Range[0,2], maxima atπ/4+kπ and minima at3π/4+kπ. These check graph features, not the sketch.',limited=True)
A.save('diagnostic')
